-- Identity columns: GENERATED ALWAYS (data model G-01); ETL keys rows by legacy_* and never sets ids.

-- Row convention checks (plan 14.2) on every migratable table.
ALTER TABLE "users" ADD CONSTRAINT "ck_users_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));
ALTER TABLE "user_roles" ADD CONSTRAINT "ck_user_roles_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));
ALTER TABLE "user_scopes" ADD CONSTRAINT "ck_user_scopes_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));
ALTER TABLE "schools" ADD CONSTRAINT "ck_schools_legacy_source" CHECK ("legacy_source" IN ('cloud', 'my'));

-- Enums as text + check (English codes; the values of @pp/contract ROLE_CODES / SCOPE_LEVELS).
ALTER TABLE "user_roles" ADD CONSTRAINT "ck_user_roles_role"
  CHECK ("role" IN ('admin', 'school_admin', 'ppd_officer', 'teacher', 'student', 'parent', 'sponsor'));
ALTER TABLE "user_scopes" ADD CONSTRAINT "ck_user_scopes_role"
  CHECK ("role" IN ('admin', 'school_admin', 'ppd_officer', 'teacher', 'student', 'parent', 'sponsor'));
ALTER TABLE "user_scopes" ADD CONSTRAINT "ck_user_scopes_level"
  CHECK ("level" IN ('national', 'state', 'district', 'school', 'class', 'self'));
-- Mirrors the contract refinement of ScopeSchema.
ALTER TABLE "user_scopes" ADD CONSTRAINT "ck_user_scopes_shape" CHECK (
  ("level" <> 'state' OR "state_code" IS NOT NULL)
  AND ("level" <> 'district' OR "district_code" IS NOT NULL)
  AND ("level" NOT IN ('school', 'class') OR "school_id" IS NOT NULL)
);
ALTER TABLE "sessions" ADD CONSTRAINT "ck_sessions_active_role"
  CHECK ("active_role" IN ('admin', 'school_admin', 'ppd_officer', 'teacher', 'student', 'parent', 'sponsor'));
ALTER TABLE "sessions" ADD CONSTRAINT "ck_sessions_mode_kind" CHECK ("mode_kind" IS NULL OR "mode_kind" IN ('mod_pelajar'));
ALTER TABLE "sessions" ADD CONSTRAINT "ck_sessions_mode_return_role" CHECK (
  "mode_return_role" IS NULL
  OR "mode_return_role" IN ('admin', 'school_admin', 'ppd_officer', 'teacher', 'student', 'parent', 'sponsor')
);
-- The three mode columns are all null (normal operation) or all set (mode on).
ALTER TABLE "sessions" ADD CONSTRAINT "ck_sessions_mode_complete" CHECK (
  ("mode_kind" IS NULL AND "mode_return_role" IS NULL AND "mode_since" IS NULL)
  OR ("mode_kind" IS NOT NULL AND "mode_return_role" IS NOT NULL AND "mode_since" IS NOT NULL)
);
ALTER TABLE "users" ADD CONSTRAINT "ck_users_grade" CHECK ("grade" IS NULL OR "grade" BETWEEN 1 AND 11);
ALTER TABLE "login_attempts" ADD CONSTRAINT "ck_login_attempts_attempts" CHECK ("attempts" >= 0);

-- Login lookups: e-mail is unique case-insensitively when present; a username is unique per school
-- (two schools may share one, error AMBIGUOUS_USERNAME), plus a global index for the ambiguity lookup.
CREATE UNIQUE INDEX "uq_users_email" ON "users" (lower("email")) WHERE "email" IS NOT NULL;
CREATE UNIQUE INDEX "uq_users_school_username" ON "users" ("school_id", lower("username"))
  WHERE "username" IS NOT NULL AND "school_id" IS NOT NULL;
CREATE INDEX "ix_users_username_lower" ON "users" (lower("username")) WHERE "username" IS NOT NULL;
-- Sessions: sweeper and "revoke all sessions of a user" use ix_sessions_user_id / ix_sessions_expires_at.
